body {
  margin: 0;
  background: #f5f7fb;
  color: #101828;
  font-family: Inter, Arial, sans-serif;
}

.page {
  padding: 16px;
  box-sizing: border-box;
}

.hero {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 18px;
  background: #101828;
  color: white;
  border-radius: 8px;
  padding: 16px;
}

.hero span {
  color: #98a2b3;
  font-size: 11px;
  text-transform: uppercase;
  font-weight: 900;
}

.hero h1 {
  margin: 4px 0;
  font-size: 27px;
  line-height: 1.1;
}

.hero p {
  margin: 0;
  color: #d0d5dd;
  font-size: 12px;
}

button {
  height: 38px;
  border: 0;
  border-radius: 7px;
  background: white;
  color: #101828;
  font-weight: 900;
  padding: 0 14px;
  cursor: pointer;
}

.kpis {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 10px;
  margin-top: 12px;
}

.kpis > div,
section {
  background: white;
  border: 1px solid #d0d5dd;
  border-radius: 8px;
  padding: 12px;
}

.kpis span {
  display: block;
  color: #667085;
  font-size: 10px;
  text-transform: uppercase;
  font-weight: 900;
  margin-bottom: 5px;
}

.kpis strong {
  display: block;
  font-size: 18px;
  line-height: 1.15;
}

.kpis .warn {
  border-color: #f97316;
  border-left: 5px solid #f97316;
}

.grid-main {
  display: grid;
  grid-template-columns: 1.35fr 0.65fr;
  gap: 12px;
  margin-top: 12px;
}

.grid-two {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 12px;
}

.section-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}

.section-head h2 {
  margin: 0;
  font-size: 16px;
}

.section-head span {
  color: #667085;
  font-size: 12px;
  font-weight: 800;
}

.daily-chart {
  height: 210px;
  display: flex;
  gap: 7px;
  align-items: flex-end;
  border-top: 1px solid #eaecf0;
  padding-top: 12px;
}

.bar-wrap {
  flex: 1;
  min-width: 24px;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  text-align: center;
}

.bar {
  background: #2563eb;
  border-radius: 6px 6px 0 0;
  min-height: 6px;
  position: relative;
}

.bar b {
  position: absolute;
  left: 50%;
  bottom: 100%;
  transform: translateX(-50%);
  margin-bottom: 4px;
  font-size: 10px;
  color: #344054;
  white-space: nowrap;
}

.bar-wrap small {
  margin-top: 5px;
  color: #667085;
  font-size: 10px;
}

.hour-chart {
  display: grid;
  gap: 8px;
}

.hour-row {
  display: grid;
  grid-template-columns: 44px 1fr 72px;
  gap: 8px;
  align-items: center;
  font-size: 11px;
}

.hour-row > div {
  height: 9px;
  background: #eaecf0;
  border-radius: 999px;
  overflow: hidden;
}

.hour-row i {
  display: block;
  height: 100%;
  background: #0f766e;
  border-radius: inherit;
}

.hour-row b {
  text-align: right;
}

.list {
  display: grid;
  gap: 7px;
}

.list.compact {
  gap: 6px;
}

.list-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  border: 1px solid #eaecf0;
  border-radius: 7px;
  padding: 9px;
  align-items: center;
}

.list-row b {
  display: block;
  font-size: 13px;
}

.list-row span {
  display: block;
  color: #667085;
  font-size: 11px;
  margin-top: 2px;
}

.list-row strong {
  white-space: nowrap;
  font-size: 13px;
  text-align: right;
}

.open-docs {
  margin-top: 12px;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th {
  background: #f2f4f7;
  color: #344054;
  font-size: 11px;
  text-align: left;
  padding: 9px 8px;
  border-bottom: 1px solid #d0d5dd;
}

td {
  padding: 8px;
  font-size: 12px;
  border-bottom: 1px solid #eaecf0;
}

.right {
  text-align: right;
  white-space: nowrap;
}

.open {
  color: #b42318;
  font-weight: 900;
}

.footer {
  margin-top: 12px;
  color: #667085;
  font-size: 10px;
  text-align: center;
}

@media print {
  body {
    background: white;
  }
  .page {
    padding: 0;
  }
  button {
    display: none;
  }
  .hero,
  .kpis > div,
  section {
    box-shadow: none;
  }
}

